-- 1011: the academy's Fleet and Finance paths get the two-step deposit review (Release 35, part RR; docs/changes/2026-11-08-r35-deposit-review.md).
-- No applied migration is edited. One section on each path (supabase/seed/academy/r35rr.mjs, generated below): Fleet checks a return
-- angle by angle and signs the seven items; Finance double-checks, checks the tolls and every ticket place, the sweep and the
-- countdowns. Staff who had passed every section of their paths keep a week before the new section holds them (as 0731, 0802 and
-- 0932 did); nothing is reset.
create temp table r35rr_done on commit drop as
select distinct e.user_id from academy_enrollments e where e.path_code in ('fleet', 'finance') and app.academy_done(e.user_id);

-- ACADEMY 1011 START (generated by supabase/seed/1011_gen_academy.mjs from supabase/seed/academy/r35rr.mjs; do not edit by hand)
-- ACADEMY 1011 END

update academy_enrollments e set lock_from = greatest(e.lock_from, now() + interval '7 days')
  from r35rr_done d where e.user_id = d.user_id and e.gate;
