insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-fleet-deposit-review', 'Checking a return before the deposit is released', 'Compare the pickup and return photos angle by angle, then sign the seven items. Finance double-checks after you.', array['va/fleet']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), 1, 'Your part comes first', '[{"caption":"A To do for each return","say":"Every returned booking with a deposit gives you a To do: check the return before the deposit is released.","visual":{"kind":"title","heading":"Deposit review","text":"Fleet first, then Finance"}},{"caption":"Angle by angle","say":"Open the review. The pickup and return photos sit side by side for each angle: front, sides, rear, wheels, inside and the dashboard.","visual":{"kind":"list","heading":"Compare","items":["Front and corners","Each side","Rear","Wheels","Inside and trunk","Dashboard"]}},{"caption":"The seven items","say":"Sign each item: fuel, kilometres, damage, late return, cleaning, tickets and highway tolls. The site shows what it already knows beside each one.","visual":{"kind":"list","heading":"The checklist","items":["Fuel","Kilometres","Damage","Late return","Cleaning","Tickets","Highway tolls"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), 2, 'OK or an issue', '[{"caption":"OK","say":"Nothing to bill for that item: choose OK and sign.","visual":{"kind":"rule","heading":"OK","text":"Nothing found: OK.","tone":"ok"}},{"caption":"An issue","say":"Something to bill: choose Issue, say what you found, put the amount when you know it, and the return photo numbers that show it.","visual":{"kind":"steps","heading":"An issue","items":["Choose Issue","Say what you found","Amount, if known","Photo numbers, for example 3, 7"]}},{"caption":"After you","say":"Once all seven are signed, Finance gets a To do to double-check. You cannot change an item Finance already checked: ask Finance.","visual":{"kind":"chat","lines":[{"who":"you","text":"All seven signed, a scratch on the rear bumper, photo 4."},{"who":"app","text":"Finance has it to double-check."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), 1, 'Who checks a return first?', '["Finance","Fleet","The renter","Nobody"]'::jsonb, 1, 'Fleet signs each item first; Finance double-checks after.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), 2, 'What do you compare for damage?', '["Only the return photos","The pickup and return photos, angle by angle","The listing photos","The renter''s photos only"]'::jsonb, 1, 'Side by side, one angle at a time.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), 3, 'You find a new scratch. What do you sign?', '["OK","Issue, with what you found, the amount if known and the photo numbers","Nothing","Tell the renter"]'::jsonb, 1, 'An issue needs a note; add the amount and the photos.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), 4, 'Which items are on the checklist?', '["Fuel and damage only","Fuel, kilometres, damage, late return, cleaning, tickets and highway tolls","Only tickets","Only the keys"]'::jsonb, 1, 'Seven items, every return.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), 5, 'Can the deposit be released before you sign?', '["Yes, by Finance","No: it stays held until Fleet and Finance signed every item, unless an Admin gives the reason","Yes, after a day","Only on weekends"]'::jsonb, 1, 'The review holds the deposit.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-r35-fleet-deposit-review'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-finance-deposit-review', 'Double-checking a deposit review, tolls and tickets', 'Double-check each item Fleet signed, check the highway tolls and every ticket place, then bill or release. The sweep is Monday, Wednesday and Friday.', array['va/finance']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 1, 'After Fleet', '[{"caption":"Your To do","say":"When Fleet signed all seven items you get a To do: double-check the deposit review.","visual":{"kind":"title","heading":"Double-check","text":"Each item Fleet signed"}},{"caption":"Each item","say":"Read what Fleet found and the photos, then Double-check: OK or Issue, with the amount to bill.","visual":{"kind":"steps","heading":"Double-check","items":["Read Fleet''s finding","Look at the photos","OK or Issue","Amount to bill"]}},{"caption":"Not your own","say":"Someone else double-checks a Fleet check you signed yourself.","visual":{"kind":"rule","heading":"Two people","text":"The person who signed for Fleet does not double-check it.","tone":"stop"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 2, 'Tolls and tickets', '[{"caption":"Highway tolls","say":"Open the toll operator''s site from the review, search the plate for the rental dates, then double-check the Highway tolls item.","visual":{"kind":"title","heading":"Highway tolls","text":"Search the plate for the dates"}},{"caption":"Every ticket place","say":"Each city and camera program has its lookup link. Open each one, search the plate, and record None found or A ticket.","visual":{"kind":"list","heading":"Some places","items":["Toronto","Mississauga","Brampton","Durham Region towns","Regional and provincial cameras"]}},{"caption":"A ticket","say":"A ticket you record is logged in Tolls and tickets with the place and the plate, and matched to the booking there.","visual":{"kind":"rule","heading":"A ticket","text":"Record it once: it goes to Tolls and tickets.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 3, 'Bill or release, on time', '[{"caption":"Then decide","say":"Once every item is double-checked, bill what is owed with the charge after the return on Money, or release the deposit.","visual":{"kind":"money","heading":"Example","rows":[["Fuel, two eighths","$20.00"],["Parking ticket","$45.00"]],"total":"Billed from the deposit"}},{"caption":"The sweep","say":"Monday, Wednesday and Friday a To do lists every plate returned since the last sweep and every booking still inside the toll and ticket window. Check them in one go.","visual":{"kind":"list","heading":"The sweep","items":["Monday","Wednesday","Friday"]}},{"caption":"Countdowns","say":"Money shows the time left on each deposit hold, each deposit owed back and each plan payment. Red within 24 hours or late, amber within 48.","visual":{"kind":"rule","heading":"Countdowns","text":"Work the red ones first.","tone":"stop"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 1, 'When can you double-check an item?', '["Any time","After Fleet signed it","Only after the release","Never"]'::jsonb, 1, 'Fleet first, then Finance.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 2, 'What must be done before the Tickets item?', '["Nothing","Every ticket place checked: None found or A ticket","A call to the renter","The release"]'::jsonb, 1, 'Every place, each with its result.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 3, 'You find a parking ticket. What happens when you record it?', '["Nothing","It is logged in Tolls and tickets with the place and the plate","The renter is charged at once","It is deleted"]'::jsonb, 1, 'It joins the toll and ticket queue.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 4, 'When is the sweep?', '["Every day","Monday, Wednesday and Friday","Once a month","Only when asked"]'::jsonb, 1, 'Three times a week (Program settings).') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-finance-deposit-review'), 5, 'A countdown is red. What does it mean?', '["Nothing","Less than 24 hours left, or late","More than a week left","Paid"]'::jsonb, 1, 'Red within 24 hours or late, amber within 48.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'finance', (select id from academy_sections where slug = 'new-r35-finance-deposit-review'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'finance' on conflict (path_code, section_id) do nothing;
